function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  const n = grid.length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square (n x n).';
    if (row.some(v => v !== -1 && v !== 0 && v !== 1)) return 'Each cell is -1, 0 or 1.';
  }
  if (grid[0][0] === -1 || grid[n - 1][n - 1] === -1) return 'The top-left and bottom-right cells cannot be thorns.';
  return null;
}

