function cherryPickup(grid) {
  const n = grid.length;
  let dp = Array.from({ length: n }, () => new Array(n).fill(-1));
  dp[0][0] = grid[0][0];
  for (let step = 1; step <= 2 * n - 2; step++) {
    const next = Array.from({ length: n }, () => new Array(n).fill(-1));
    const low = Math.max(0, step - (n - 1));
    const high = Math.min(n - 1, step);
    for (let r1 = low; r1 <= high; r1++) {
      for (let r2 = low; r2 <= high; r2++) {
        const c1 = step - r1;
        const c2 = step - r2;
        if (grid[r1][c1] === -1 || grid[r2][c2] === -1) continue;
        let best = dp[r1][r2];
        if (r1 > 0) best = Math.max(best, dp[r1 - 1][r2]);
        if (r2 > 0) best = Math.max(best, dp[r1][r2 - 1]);
        if (r1 > 0 && r2 > 0) best = Math.max(best, dp[r1 - 1][r2 - 1]);
        if (best < 0) continue;
        const gained = r1 === r2 ? grid[r1][c1] : grid[r1][c1] + grid[r2][c2];
        next[r1][r2] = best + gained;
      }
    }
    dp = next;
  }
  return Math.max(0, dp[n - 1][n - 1]);
}

