function cherryPickup(grid) {
  // Try every first leg explicitly, clear its cherries, then find the best way back with a one-path DP.
  const n = grid.length;
  let answer = 0;
  const bestReturn = field => {
    const best = Array.from({ length: n }, () => new Array(n).fill(-Infinity));
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        if (field[r][c] === -1) continue;
        if (r === 0 && c === 0) { best[r][c] = field[r][c]; continue; }
        const from = Math.max(r > 0 ? best[r - 1][c] : -Infinity, c > 0 ? best[r][c - 1] : -Infinity);
        best[r][c] = from + field[r][c];
      }
    }
    return best[n - 1][n - 1];
  };
  const walk = (r, c, cells) => {
    if (r >= n || c >= n || grid[r][c] === -1) return;
    cells.push([r, c]);
    if (r === n - 1 && c === n - 1) {
      const field = grid.map(row => row.slice());
      let picked = 0;
      for (const [x, y] of cells) { picked += field[x][y]; field[x][y] = 0; }
      const back = bestReturn(field);
      if (back !== -Infinity) answer = Math.max(answer, picked + back);
    } else {
      walk(r + 1, c, cells);
      walk(r, c + 1, cells);
    }
    cells.pop();
  };
  walk(0, 0, []);
  return answer;
}

