function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  const thorns = rand() * (size === 'large' ? 0.22 : 0.45);
  const cherries = 0.2 + rand() * 0.7;
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => {
    const roll = rand();
    if (roll < thorns) return -1;
    return rand() < cherries ? 1 : 0;
  }));
  if (grid[0][0] === -1) grid[0][0] = 1;
  if (grid[n - 1][n - 1] === -1) grid[n - 1][n - 1] = 1;
  return [grid];
}
